function sumSegments(segs){
  segs=segs||[]; var ms=0;
  for(var i=0;i<segs.length;i++){ var d=(+segs[i].end)-(+segs[i].start); if(d>0) ms+=d; }
  return {ms:ms, hours:Math.round(ms/36000)/100, count:segs.length};
}
function fmt(ms){
  ms=Math.max(0,Math.round(ms));
  var h=Math.floor(ms/3600000), m=Math.floor((ms%3600000)/60000), s=Math.floor((ms%60000)/1000);
  function pad(x){return (x<10?'0':'')+x;}
  return h+':'+pad(m)+':'+pad(s);
}
var EXPORTS={sumSegments:sumSegments, fmt:fmt};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WorkTimerForgePure = EXPORTS; }
